const headers = $json.headers ?? {};
const body = $json.body ?? {};
const secret = headers['x-agent-secret'] || headers['X-Agent-Secret'] || body.agent_secret || '';
const expected = $env.AGENT_WEBHOOK_SECRET || '';
if (!secret || !expected || secret !== expected) {
  throw new Error('unauthorized: x-agent-secret must equal AGENT_WEBHOOK_SECRET');
}
const stage = body.approval_stage;
if (!['analysis','plan','final_delivery'].includes(stage)) {
  throw new Error('Invalid approval_stage');
}
return [{json: {...body, agent_secret: secret, reviewer_type: 'human'}}];

