INSERT INTO content_approvals (job_id, approval_stage, decision, reviewer_id, reviewer_type, reviewer_notes)
VALUES (NULLIF('{{$json.job_id}}','')::uuid, '{{$json.approval_stage}}', COALESCE('{{$json.decision}}','approved'), 'human:' || COALESCE('{{$json.reviewer_name}}','operator'), 'human', COALESCE('{{$json.notes}}',''));
UPDATE content_jobs SET status=CASE WHEN '{{$json.approval_stage}}'='analysis' THEN 'analysis_complete'::job_status WHEN '{{$json.approval_stage}}'='plan' THEN 'generating_outputs'::job_status WHEN '{{$json.approval_stage}}'='final_delivery' THEN 'delivery_ready'::job_status ELSE status END, updated_at=now() WHERE id=NULLIF('{{$json.job_id}}','')::uuid;
SELECT NULLIF('{{$json.job_id}}','') AS job_id, '{{$json.approval_stage}}' AS approval_stage, COALESCE('{{$json.decision}}','approved') AS decision;
